// Staff of the Ages
// status: planned
// requires: static rule BlockedAsThoughLacking
// Creatures with landwalk abilities can be blocked as though they didn't have those abilities.
#[allow(unused_imports)] use cantrip_api::*;
#[allow(unused_variables)] fn ability_0_affects(q: &dyn LayerQuery, source: ObjectId, affected: ObjectId, so_far: &Chars) -> bool { let asker = &Asker::new(source, q.controller(source)); ((*so_far).is(CardType::Creature) && ((*so_far).keywords.has(Keyword::Islandwalk) || (*so_far).keywords.has(Keyword::Plainswalk) || (*so_far).keywords.has(Keyword::Swampwalk) || (*so_far).keywords.has(Keyword::Mountainwalk) || (*so_far).keywords.has(Keyword::Forestwalk) || (*so_far).keywords.has(Keyword::NonbasicLandwalk) || (*so_far).keywords.has(Keyword::LegendaryLandwalk))) }
#[allow(unused_variables)] fn ability_0_0_rule(q: &dyn Query, asker: &Asker, id: ObjectId) -> bool { (q.chars(id).is(CardType::Creature) && (q.chars(id).keywords.has(Keyword::Islandwalk) || q.chars(id).keywords.has(Keyword::Plainswalk) || q.chars(id).keywords.has(Keyword::Swampwalk) || q.chars(id).keywords.has(Keyword::Mountainwalk) || q.chars(id).keywords.has(Keyword::Forestwalk) || q.chars(id).keywords.has(Keyword::NonbasicLandwalk) || q.chars(id).keywords.has(Keyword::LegendaryLandwalk))) }
planned_item!("static-rule-blocked-as-though-lacking" => blocked_as_though_lacking: ability_0_0_rule);

